dst = "/home/miccao/drc/newdeck"
raw = open(dst, "rb").read()
print("total bytes", len(raw))
print("has CRLF:", raw.count(b"\r\n"), "has lone LF:", raw.count(b"\n") - raw.count(b"\r\n"), "has CR:", raw.count(b"\r"))
lines = raw.splitlines()
print("num lines (splitlines):", len(lines))

def show(lo, hi):
    for i in range(lo - 1, min(hi, len(lines))):
        print("{0:5d} {1}".format(i + 1, repr(lines[i])))

# find the changed rules in newdeck
text = raw.decode("utf-8", errors="replace")
tlines = text.splitlines()
for i, ln in enumerate(tlines, 1):
    if ln.strip().startswith("R_C_M0C_ENC_01_H"):
        show(i, i + 10)
    if ln.strip().startswith("R_C_M0C_ENC_02_H"):
        show(i, i + 10)
    if ln.strip().startswith("R_C_MT2_F_01_M"):
        show(i, i + 12)
